#pragma once
#include <stdexcept>
static void modernTests(Window &w,const QString &output,std::function<void(QString,bool)> check){
 auto reset=[&]{w.testMode=true;w.logicalView=false;w.model=Model::example();w.filePath.clear();w.history.clear();w.selection.clear();w.selectionIds.clear();w.en=false;w.outlineSearch->clear();w.buildMenus();w.refresh();w.fit();};reset();
 w.outlineSearch->setText("quant");int visible=0;QString found;for(QTreeWidgetItemIterator it(w.tree);*it;++it)if(!(*it)->isHidden()){++visible;found=(*it)->data(0,Qt::UserRole).toString();}
 check("Search shows matching attribute and its entity context",visible==2&&found=="quantita");
 auto original=w.model.json();QKeyEvent enter(QEvent::KeyPress,Qt::Key_Return,Qt::NoModifier);QApplication::sendEvent(w.outlineSearch,&enter);check("Search Enter selects and centers without editing the model",w.selection=="quantita"&&w.model.json()==original);w.outlineSearch->clear();
 w.mode=2;w.applyTheme();check("Night search placeholder retains readable contrast",Theme::contrast(qApp->palette().color(QPalette::PlaceholderText),qApp->palette().color(QPalette::Base))>=4.5);w.mode=1;w.applyTheme();
 w.zoomBox->setValue(175);check("Zoom field applies requested percentage",qAbs(w.view->transform().m11()-1.75)<.001);w.view->zoom(.5);check("Zoom field follows wheel and other zoom commands",w.zoomBox->value()==88);
 w.selectOnly("contiene");check("Selection hint explains relationship roles",w.contextHint->text().contains("A e B"));w.en=true;w.buildMenus();w.updateStatus();check("Search and contextual guidance fully switch to English",w.outlineSearch->placeholderText()=="Find elements…"&&w.contextHint->text().contains("A and B"));reset();
 auto before=w.model.json();const int index=w.history.index();w.change("Injected failure",[](Model &m){m.get("ordine")->name="Not committed";throw std::runtime_error("test");});check("Exception during a mutation leaves model and undo stack intact",w.model.json()==before&&w.history.index()==index);
 w.change("Invalid reference",[](Model &m){m.get("data")->owner="missing";});check("Invalid candidate edit is rejected before replacing live model",w.model.json()==before&&w.history.index()==index);
 w.selectOnly("ordine");w.dragBefore=w.model;w.dragIds=w.selectionIds;w.moveDrag({200000,0});w.finishGroupDrag();check("Out-of-bounds drag rolls back to a loadable document",w.model.json()==before&&w.history.index()==index);
 // A deferred edit must never target a newly opened document sharing the same IDs.
 w.selectOnly("ordine");w.formWidget->findChild<QLineEdit*>()->setText("Old pending edit");w.formWidget->findChild<QPushButton*>("applyProperties")->click();++w.documentEpoch;w.model=Model::example();w.history.clear();w.refresh();qApp->processEvents();check("Deferred property edit cannot cross a document change",w.model.get("ordine")->name=="Ordine"&&w.history.isClean());
 QString error;Model parsed=Model::example();check("Oversized in-memory JSON is rejected atomically",!Model::parse(QByteArray(20*1024*1024+1,' '),parsed,error)&&parsed.json()==Model::example().json());
 QTemporaryDir temporary(output+"/resilience-XXXXXX");check("Recovery test uses an isolated writable folder",temporary.isValid());
 const auto path=temporary.path()+"/project.schema";auto first=Model::example(),second=first;second.get("ordine")->name="Updated";
 check("Save with backup keeps the previous valid project",saveWithBackup(path,first,error)&&saveWithBackup(path,second,error)&&loadModel(path+".bak",parsed,error)&&parsed.json()==first.json()&&loadModel(path,parsed,error)&&parsed.json()==second.json());
 const auto denied=temporary.path()+"/blocked.schema";saveModel(denied,first,error);QDir().mkpath(denied+".bak");check("Backup failure never overwrites the existing project",!saveWithBackup(denied,second,error)&&loadModel(denied,parsed,error)&&parsed.json()==first.json());
 check("Write failure leaves the in-memory model unchanged",!saveWithBackup(temporary.path()+"/absent/project.schema",w.model,error)&&w.model.json()==Model::example().json());
 auto savedRecoveryPath=w.recoveryPath;w.recoveryPath=temporary.path()+"/recovery.schema";w.ownsRecovery=false;w.change("First edit",[&](Model&m){m=second;});w.testMode=false;bool firstRecovery=w.writeRecovery();w.testMode=true;w.change("Second edit",[](Model&m){m.get("ordine")->name="Newest";});w.testMode=false;bool secondRecovery=w.writeRecovery();w.testMode=true;
 check("Recovery rotates a previous valid generation",firstRecovery&&secondRecovery&&loadModel(w.recoveryPath+".previous",parsed,error)&&parsed.json()==second.json());
 {QFile corrupt(w.recoveryPath);if(corrupt.open(QIODevice::WriteOnly))corrupt.write("{truncated");}
 QTimer::singleShot(0,&w,[&]{for(auto widget:qApp->topLevelWidgets())if(auto box=qobject_cast<QMessageBox*>(widget))if(box->button(QMessageBox::Yes))box->button(QMessageBox::Yes)->click();});w.recover();check("Corrupted latest recovery falls back to previous valid project",w.model.json()==second.json()&&!w.history.isClean()&&w.filePath.isEmpty());
 w.ownsRecovery=false;w.testMode=false;bool retained=w.writeRecovery();w.testMode=true;check("Unclaimed recovery is retained before a new session overwrites it",retained&&!QDir(temporary.path()).entryList({"recovery.schema.retained-*"},QDir::Files).isEmpty());
 w.clearRecovery();check("Explicit successful cleanup removes active recovery generations",!QFile::exists(w.recoveryPath)&&!QFile::exists(w.recoveryPath+".previous"));
 w.recoveryPath=temporary.path()+"/fallback-only.schema";saveModel(w.recoveryPath+".previous",first,error);w.testMode=false;bool fallbackOnly=w.writeRecovery();w.testMode=true;check("Declined fallback-only recovery is archived before new autosaves",fallbackOnly&&!QDir(temporary.path()).entryList({"fallback-only.schema.previous.retained-*"},QDir::Files).isEmpty());w.clearRecovery();
 w.recoveryPath=savedRecoveryPath;reset();
 // Long acyclic input is safe to validate; excessively deep translation fails clearly.
 Model deep;for(int i=0;i<600;++i){Object e;e.id=QString("e%1").arg(i);e.name=e.id;e.kind="entity";deep.objects<<e;if(i<599){Object isa;isa.id=QString("i%1").arg(i);isa.kind="isa";isa.name="ISA";isa.a=e.id;isa.b=QString("e%1").arg(i+1);deep.objects<<isa;}else{Object key;key.id="key";key.kind="attribute";key.name="id";key.owner=e.id;key.key=true;deep.objects<<key;}}
 check("Long ISA chain validates without recursive stack use",deep.issues().isEmpty());QStringList errors;generateLogical(deep,{},errors,true);check("Excessively deep logical dependency fails with a useful diagnostic",errors.join(" ").contains("limit 256"));
 for(int i=0;i<110;++i){w.change("History stress",[i](Model&m){m.get("ordine")->name=QString("Order%1").arg(i);});}
 check("Undo history has a bounded snapshot count",w.history.count()==100&&!w.history.isClean());
 reset();w.selectOnly("contiene");qApp->processEvents();w.grab().save(output+"/qt6-modern-it.png");w.en=true;w.mode=2;w.applyTheme();w.buildMenus();w.refresh();qApp->processEvents();w.grab().save(output+"/qt6-modern-night-en.png");reset();
}

