 w.logicalView=false;w.model=shopExample();w.selection.clear();w.selectionIds.clear();w.uml=true;w.mode=1;w.view->gridVisible=true;w.applyTheme();w.buildMenus();w.refresh();w.fit();qApp->processEvents();w.grab().save(output+"/shop-window.png");
 w.outline->hide();w.properties->hide();qApp->processEvents();w.fit();w.view->grab().save(output+"/shop-grid.png");
