 {QScopedPointer<QDialog> dialog(w.mappingExplanationDialog());dialog->show();qApp->processEvents();auto browser=dialog->findChild<QTextBrowser*>("learningSummary");check("Concise explanation fits native screen and keeps warnings visible",dialog->frameGeometry().height()<=screen.height()&&browser->toPlainText().contains("Cosa resta da controllare"));dialog->grab().save(output+"/learning-cards.png");}
